import pandas as pd, re, pathlib
root=pathlib.Path('/mnt/data')
a=pd.read_csv(root/'eldamo_strict_chain_audit.csv').fillna('')
n=pd.read_csv(root/'eldamo_rule_commentary_audit.csv').fillna('')
e=pd.read_csv(root/'eldamo_strict_chain_evidence.csv').fillna('')
ids=[15,20,21,25,27,28,29,32,35,44,67,69,71,72,74,79,85,91,93]
# Manually categorized ONLY from observed source notes, not conjectured histories.
assess={
15:('условно совместима','Спирантизация медиального b не действует после носовых; более позднее β → v зависит от сохранения β и редакции.','Проверить вокалическое окружение b и редакционную принадлежность примера.'),
20:('условно совместима','Потеря ɣ из g в Quenya описана как обычная, но заметка различает начальную позицию, Parmaquesta и Tarquesta.','Проверить позицию g в форме и хронологию ослабления/исчезновения.'),
21:('повышенная неопределённость','Заметка о pt/kt → ɸt/xt рассматривает конкурирующие исторические редакции, а также переход pt → ps.','Разделить варианты OP1/OP2 и установить, к какой именно редакции относится пример.'),
25:('повышенная неопределённость','Оглушение g перед t относится к ранним стадиям, но итог kt → xt имеет редакционные альтернативы.','Сопоставить происхождение группы gt и позднее продолжение kt по одной редакции.'),
27:('повышенная неопределённость','Преобразование kn → kt имеет специальные условия после глухих смычных; kt → xt редакционно вариативно.','Проверить точную ветвь правила и источник примера.'),
28:('повышенная неопределённость','Упрощение придыхания после глухой смычной и последующий переход kt → xt требуют подтверждения относительного порядка.','Проверить, что в выбранном примере придыхание действительно исчезает до спирантизации.'),
29:('условно совместима','Заметка прямо относит x → h к позиции вне сочетания xt, с различием начальной и срединной позиции по времени.','Указать позицию x и ступень PQ/TQ; не распространять на xt.'),
32:('условно совместима','Примечание объясняет pm → pp через краткое промежуточное pʍ; формула pw является условным упрощением.','Представить уточнённую ветвь pm → pʍ → pp, если она поддержана данной редакцией.'),
35:('условно совместима','Заметки фиксируют pʰ → ɸ и затем ɸ → f, но первый переход датируется границей AQ/PQ по-разному в OP1 и OP2.','Не закреплять первый переход за AQ без оговорки; проверить границу PQ.'),
44:('диалектное ограничение','θ → s прямо описан для Ñoldorin Quenya; в Vanyarin θ сохраняется.','Маркировать конец цепочки как Ñoldorin Quenya, а не обще-квенийский.'),
67:('требует первичного текста','В предварительном извлечении нет развёрнутой заметки для одного или обоих среднепериодных правил.','Проверить источник PE19/45, особенно pt → ps и датировку.'),
69:('требует первичного текста','Нет полной извлечённой заметки; формулы относятся к среднему периоду и могут зависеть от согласного окружения.','Проверить первоисточник и порядок двух законов.'),
71:('требует первичного текста','Нет развёрнутой извлечённой заметки для двух среднепериодных правил.','Сопоставить Ety/YAT и обоснование dm → nm → nw.'),
72:('требует первичного текста','Нет извлечённого развёрнутого комментария по последовательности g → ɣ → ø.','Проверить локализацию и окружение g в среднепериодном источнике.'),
74:('требует первичного текста','Не хватает развёрнутой заметки к этапам gm → ŋm → ŋgw.','Проверить Ety/NAK и относительную хронологию.'),
79:('требует первичного текста','Не извлечены развёрнутые заметки к kʰn → kt и kt → xt среднепериодной редакции.','Проверить PE22/103 и необходимость промежуточного звука.'),
85:('требует первичного текста','Извлечённых пояснений среднепериодных правил недостаточно для датировки pʰ → ɸ → f.','Проверить PE22/102 и согласование двух процессов.'),
91:('требует первичного текста','Отсутствуют развёрнутые заметки по sg → zg → sk; сочетание требует строгого учёта порядка озвончения и оглушения.','Проверить PE19/51 и фонетическое окружение.'),
93:('требует первичного текста','Среднепериодная θ → s не должна автоматически получать позднее диалектное объяснение; заметки не извлечены.','Проверить Ety/I² независимо от позднего описания Shibboleth.'),
}
rows=[]
for id in ids:
 r=a.loc[a.id==id].iloc[0]
 urls=r.rule_urls.split(' || ')
 notes=[]
 for url in urls:
  rr=n[n.rule_url==url]
  if not rr.empty:
   item=rr.iloc[0]
   notes.append(str(item.notes) if str(item.notes)!='' else '')
  else:notes.append('')
 assessment,reason,check=assess[id]
 ev=e[e.id==id]
 selected=ev.iloc[0] if len(ev) else None
 rows.append(dict(id=id,states=r.states,era=r.era,languages=r.languages,rule_titles=r.rules,rule_urls=r.rule_urls,example=r.example,source=r.matched_primary_source,article=r.matched_lexical_article,assessment=assessment,limitation=reason,next_check=check,note_coverage=f'{sum(bool(s) for s in notes)}/{len(notes)}',notes_1=notes[0][:12000] if notes else '',notes_2=notes[1][:12000] if len(notes)>1 else '',evidence_count=len(ev)))
out=pd.DataFrame(rows)
out.to_csv(root/'eldamo_textual_chain_assessment.csv',index=False)
from collections import Counter
count=Counter(out.assessment)
lines=['# Eldamo 0.8.13 — текстологический аудит 19 цепочек','',
'## Границы проверки','',
'Основание: локальный архив Eldamo 0.8.13, предыдущая выборка 101 кандидата, таблицы примеров и извлечённые развёрнутые примечания к страницам правил. Это проверка **интерпретации правил**, а не самостоятельная экспертиза всех первоисточников Tolkien (PE, VT, Ety). Приведённые цепочки имеют совпадающие примеры в каталоге, но не объявляются доказанной последовательностью языковой истории.','',
'**Особенно важно:** поздний и средний периоды *создания концепции* не следует смешивать с внутренней историей языков (Primitive → AQ → Q). Формулы могут быть редакционно альтернативны.','',
'## Итоговая оценка','',
'| Статус | Количество |','|---|---:|']
for k,v in count.items():lines.append(f'| {k} | {v} |')
lines += ['','Ни одной цепочке не присвоен статус «окончательно подтверждена первоисточниками»: для этого необходимо прочесть полные первичные публикации и проверить доказательство относительной хронологии.','',
'## Самые существенные замечания по историческому порядку','',
'- `pʰ → ɸ → f`: замечания OP1/OP2 предполагают разные привязки первого этапа к границе Ancient Quenya / Parmaquesta; граф не должен фиксировать одну датировку без выбора редакции.',
'- `tʰ → θ → s`: позднее правило `θ → s` ограничено нолдорским вариантом Quenya; ваньярский сохраняет `θ`.',
'- `kʰ → x → h`: переход `x → h` не применяется перед `t`, а для начальной и срединной позиций заметки различают стадии Parmaquesta/Tarquesta.',
'- `pm → pw → pp`: подробная заметка допускает более точную передачу промежуточного этапа `pm → pʍ → pp`; упрощённая схема `pw` не воспроизводит всю артикуляционную историю.',
'- `kt → xt`: заметка к правилу сравнивает несколько редакций и альтернативы (включая `pt → ps`); соответствующие пути не следует сливать в один недатированный закон.','',
'## Полная таблица 19 цепочек','',
'| ID | Цепочка | Словоформы | Период концепции | Оценка | Проблема |','|---:|---|---|---|---|---|']
for r in rows:
 def esc(s):return str(s).replace('|','\\|').replace('\n',' ')
 lines.append(f"| {r['id']} | `{esc(r['states'])}` | `{esc(r['example'])}` | {esc(r['era'])} | {esc(r['assessment'])} | {esc(r['limitation'])} |")
lines += ['','## Карточки и конкретные задания на проверку','']
for r in rows:
 lines += [f"### {r['id']}: `{r['states']}`",'',f"- **Пример:** `{r['example']}` ({r['source']}).",f"- **Разделы Eldamo:** {r['languages']}.",f"- **Оценка:** {r['assessment']}. {r['limitation']}",f"- **Следующая проверка:** {r['next_check']}",f"- **Полные пояснения доступны для:** {r['note_coverage']} страниц правил."]
 for j,url in enumerate(r['rule_urls'].split(' || '),1):lines.append(f'- [Правило {j} Eldamo]({url})')
 lines.append('')
lines += ['## Методологический итог','',
'19 цепочек следует считать **подмножеством кандидатов с согласованными примерами**, а не 19 филологически доказанными реконструкциями. Наиболее существенные дальнейшие операции: (1) связать каждое звено с *конкретным* местом в PE/VT/Ety, (2) размечать сегментное окружение, (3) фиксировать диалект и стадию, (4) отдельно указывать редакцию Tolkien, (5) сохранять альтернативные пути вместо искусственного слияния.','',
'В CSV `eldamo_textual_chain_assessment.csv` сохранён полный извлечённый текст заметок (где он имелся), а не только краткие выводы; пригоден для ручной проверки.','']
(root/'eldamo_textual_chain_report.md').write_text('\n'.join(lines),encoding='utf-8')
print(len(rows),dict(count));print((root/'eldamo_textual_chain_report.md').stat().st_size)
